begin;
create temp table _had_parking on commit drop as select id from public.areas where parking_lat is not null;
update public.areas set parking_lat=40.004483, parking_lng=-105.405315, parking_name='Boulder Falls parking area on CO-119 (upstream end for Boulder Slips)' where path <@ (select path from public.areas where id='co_lower_dream_canyon') and id not in (select id from _had_parking) and (lat is null or lng is null or 12742 * asin(sqrt(power(sin(radians(lat - 40.004483) / 2), 2) + cos(radians(40.004483)) * cos(radians(lat)) * power(sin(radians(lng - -105.405315) / 2), 2))) <= 4);
